1	import * as THREE from "three";
2	import { ATLAS_COLUMNS, ATLAS_ROWS, tileIndexFor } from "./atlas";
3	import { BlockId } from "./blocks";
4	import { doorBounds, isDoorBlock } from "./doors";
5	import { isRedstoneOverlay, redstoneBounds } from "./redstone";
6	import { MAX_LIGHT } from "./lighting";
7	import { VoxelWorld } from "./voxelWorld";
8	
9	export type GeometryLayers = {
10	  opaque: THREE.BufferGeometry;
11	  glass: THREE.BufferGeometry;
12	};
13	
14	type GeometryBuffers = {
15	  positions: number[];
16	  normals: number[];
17	  colors: number[];
18	  uvs: number[];
19	  // Per-vertex (skyExposure, blockLight), each 0..1. Consumed by the world
20	  // material's shader patch, which combines them with the day/night uniform.
21	  lights: number[];
22	};
23	
24	const FACE_DEFS: {
25	  dir: [number, number, number];
26	  corners: [number, number, number][];
27	}[] = [
28	  {
29	    dir: [1, 0, 0],
30	    corners: [
31	      [1, 0, 0],
32	      [1, 1, 0],
33	      [1, 1, 1],
34	      [1, 0, 1]
35	    ]
36	  },
37	  {
38	    dir: [-1, 0, 0],
39	    corners: [
40	      [0, 0, 1],
41	      [0, 1, 1],
42	      [0, 1, 0],
43	      [0, 0, 0]
44	    ]
45	  },
46	  {
47	    dir: [0, 1, 0],
48	    corners: [
49	      [0, 1, 1],
50	      [1, 1, 1],
51	      [1, 1, 0],
52	      [0, 1, 0]
53	    ]
54	  },
55	  {
56	    dir: [0, -1, 0],
57	    corners: [
58	      [0, 0, 0],
59	      [1, 0, 0],
60	      [1, 0, 1],
61	      [0, 0, 1]
62	    ]
63	  },
64	  {
65	    dir: [0, 0, 1],
66	    corners: [
67	      [1, 0, 1],
68	      [1, 1, 1],
69	      [0, 1, 1],
70	      [0, 0, 1]
71	    ]
72	  },
73	  {
74	    dir: [0, 0, -1],
75	    corners: [
76	      [0, 0, 0],
77	      [0, 1, 0],
78	      [1, 1, 0],
79	      [1, 0, 0]
80	    ]
81	  }
82	];
83	
84	function createBuffers(): GeometryBuffers {
85	  return { positions: [], normals: [], colors: [], uvs: [], lights: [] };
86	}
87	
88	function createGeometry(buffers: GeometryBuffers): THREE.BufferGeometry {
89	  const geometry = new THREE.BufferGeometry();
90	  geometry.setAttribute("position", new THREE.Float32BufferAttribute(buffers.positions, 3));
91	  geometry.setAttribute("normal", new THREE.Float32BufferAttribute(buffers.normals, 3));
92	  geometry.setAttribute("color", new THREE.Float32BufferAttribute(buffers.colors, 3));
93	  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(buffers.uvs, 2));
94	  geometry.setAttribute("aLight", new THREE.Float32BufferAttribute(buffers.lights, 2));
95	  geometry.computeBoundingSphere();
96	  return geometry;
97	}
98	
99	/**
100	 * Builds a single triangle-soup BufferGeometry for the given world region with
101	 * face culling (hidden faces skipped), per-face ambient occlusion baked into
102	 * vertex colors, and atlas UVs.
103	 */
104	export function buildGeometryRegion(
105	  world: VoxelWorld,
106	  minX: number,
107	  maxX: number,
108	  minZ: number,
109	  maxZ: number,
110	  minY = 0,
111	  maxY = world.sizeY - 1
112	): THREE.BufferGeometry {
113	  return buildGeometryBuffers(world, minX, maxX, minZ, maxZ, minY, maxY, false).opaque;
114	}
115	
116	/**
117	 * Splits clear glass from opaque terrain so the renderer can use blending
118	 * without weakening depth writes for the rest of the world.
119	 */
120	export function buildGeometryLayersRegion(
121	  world: VoxelWorld,
122	  minX: number,
123	  maxX: number,
124	  minZ: number,
125	  maxZ: number,
126	  minY = 0,
127	  maxY = world.sizeY - 1
128	): GeometryLayers {
129	  const buffers = buildGeometryBuffers(world, minX, maxX, minZ, maxZ, minY, maxY, true);
130	  return { opaque: buffers.opaque, glass: buffers.glass };
131	}
132	
133	function buildGeometryBuffers(
134	  world: VoxelWorld,
135	  minX: number,
136	  maxX: number,
137	  minZ: number,
138	  maxZ: number,
139	  minY: number,
140	  maxY: number,
141	  splitGlass: boolean
142	): { opaque: THREE.BufferGeometry; glass: THREE.BufferGeometry } {
143	  const opaque = createBuffers();
144	  const glass = createBuffers();
145	
146	  const clampedMinX = Math.max(0, minX);
147	  const clampedMaxX = Math.min(world.sizeX - 1, maxX);
148	  const clampedMinZ = Math.max(0, minZ);
149	  const clampedMaxZ = Math.min(world.sizeZ - 1, maxZ);
150	  const clampedMinY = Math.max(0, minY);
151	  const clampedMaxY = Math.min(world.sizeY - 1, maxY);
152	
153	  const pushVertex = (
154	    buffers: GeometryBuffers,
155	    x: number,
156	    y: number,
157	    z: number,
158	    nx: number,
159	    ny: number,
160	    nz: number,
161	    color: [number, number, number],
162	    u: number,
163	    v: number,
164	    light: [number, number]
165	  ) => {
166	    buffers.positions.push(x, y, z);
167	    buffers.normals.push(nx, ny, nz);
168	    buffers.colors.push(color[0], color[1], color[2]);
169	    buffers.uvs.push(u, v);
170	    buffers.lights.push(light[0], light[1]);
171	  };
172	  const materialTint = (ny: number): [number, number, number] => {
173	    const shade = ny > 0 ? 1 : ny < 0 ? 0.95 : 0.9;
174	    return [shade, shade, shade];
175	  };
176	
177	  // Light hitting a face comes from the voxel the face opens into (its outward
178	  // neighbor), sampled flat across the face like the existing AO. Returns
179	  // (skyExposure, blockLight) normalized to 0..1.
180	  const sampleFaceLight = (x: number, y: number, z: number): [number, number] => {
181	    return [world.getSky(x, y, z) / MAX_LIGHT, world.getBlockLight(x, y, z) / MAX_LIGHT];
182	  };
183	
184	  const tileUV = (block: number, ny: number): [number, number, number, number] => {
185	    const face = ny > 0 ? "top" : ny < 0 ? "bottom" : "side";
186	    const tile = tileIndexFor(block, face);
187	    const col = tile % ATLAS_COLUMNS;
188	    const row = Math.floor(tile / ATLAS_COLUMNS);
189	    const rows = ATLAS_ROWS;
190	    const pad = 0.0008;
191	    const u0 = col / ATLAS_COLUMNS + pad;
192	    const v0 = row / rows + pad;
193	    const u1 = (col + 1) / ATLAS_COLUMNS - pad;
194	    const v1 = (row + 1) / rows - pad;
195	    return [u0, v0, u1, v1];
196	  };
197	
198	  const faceOcclusion = (x: number, y: number, z: number, nx: number, ny: number, nz: number): number => {
199	    const ax = nz;
200	    const ay = 0;
201	    const az = -nx;
202	    const bx = 0;
203	    const by = 1;
204	    const bz = 0;
205	
206	    const sx = x + nx;
207	    const sy = y + ny;
208	    const sz = z + nz;
209	
210	    let occ = 0;
211	    if (world.isSolid(sx + ax, sy + ay, sz + az)) occ += 1;
212	    if (world.isSolid(sx - ax, sy - ay, sz - az)) occ += 1;
213	    if (world.isSolid(sx + bx, sy + by, sz + bz)) occ += 1;
214	    if (world.isSolid(sx - bx, sy - by, sz - bz)) occ += 1;
215	    return Math.max(0.8, 1 - occ * 0.06);
216	  };
217	
218	  const pushBlockCuboid = (
219	    target: GeometryBuffers,
220	    block: number,
221	    x: number,
222	    y: number,
223	    z: number,
224	    minX: number,
225	    maxX: number,
226	    minY: number,
227	    maxY: number,
228	    minZ: number,
229	    maxZ: number
230	  ) => {
231	    for (const face of FACE_DEFS) {
232	      const nx = face.dir[0];
233	      const ny = face.dir[1];
234	      const nz = face.dir[2];
235	      const color = materialTint(ny);
236	      const light = sampleFaceLight(x + nx, y + ny, z + nz);
237	      const [u0, v0, u1, v1] = tileUV(block, ny);
238	      const corners = face.corners.map(([cx, cy, cz]) => [x + (cx ? maxX : minX), y + (cy ? maxY : minY), z + (cz ? maxZ : minZ)] as const);
239	      const [a, b, c, d] = corners;
240	      pushVertex(target, ...a, nx, ny, nz, color, u0, v1, light);
241	      pushVertex(target, ...b, nx, ny, nz, color, u0, v0, light);
242	      pushVertex(target, ...c, nx, ny, nz, color, u1, v0, light);
243	      pushVertex(target, ...a, nx, ny, nz, color, u0, v1, light);
244	      pushVertex(target, ...c, nx, ny, nz, color, u1, v0, light);
245	      pushVertex(target, ...d, nx, ny, nz, color, u1, v1, light);
246	    }
247	  };
248	
249	  for (let y = clampedMinY; y <= clampedMaxY; y += 1) {
250	    for (let z = clampedMinZ; z <= clampedMaxZ; z += 1) {
251	      for (let x = clampedMinX; x <= clampedMaxX; x += 1) {
252	        const block = world.get(x, y, z);
253	        if (block === BlockId.Air) continue;
254	        const target = splitGlass && block === BlockId.Glass ? glass : opaque;
255	        if (isDoorBlock(block)) {
256	          const bounds = doorBounds(block)!;
257	          pushBlockCuboid(target, block, x, y, z, bounds.minX, bounds.maxX, 0, 1, bounds.minZ, bounds.maxZ);
258	          continue;
259	        }
260	        // Redstone overlays are small floor-mounted boxes (flat wire, a lever
261	        // base, a torch stub) — like doors, they mesh as inset cuboids with no
262	        // neighbor culling either way.
263	        if (isRedstoneOverlay(block)) {
264	          const bounds = redstoneBounds(block)!;
265	          pushBlockCuboid(target, block, x, y, z, bounds.minX, bounds.maxX, bounds.minY, bounds.maxY, bounds.minZ, bounds.maxZ);
266	          continue;
267	        }
268	        for (const face of FACE_DEFS) {
269	          const nx = face.dir[0];
270	          const ny = face.dir[1];
271	          const nz = face.dir[2];
272	          const neighbor = world.get(x + nx, y + ny, z + nz);
273	          if (block === BlockId.Water || block === BlockId.Glass) {
