    mount(fx, cart);
    run(fx, 1, input({ crouch: true }));
    expect(fx.player.mountedVehicleId).toBeNull();
    expect(cart.rider).toBeNull();
  });
});

describe("coasting minecarts", () => {
  test("a riderless cart coasts on and friction parks it", () => {
