107	const HORIZONTAL: ReadonlyArray<readonly [number, number]> = [
108	  [1, 0],
109	  [-1, 0],
110	  [0, 1],
111	  [0, -1]
112	];
113	
114	const FACES: ReadonlyArray<readonly [number, number, number]> = [
115	  [1, 0, 0],
116	  [-1, 0, 0],
117	  [0, 1, 0],
118	  [0, -1, 0],
119	  [0, 0, 1],
120	  [0, 0, -1]
121	];
122	
123	export function tickRedstone(state: GameState, dt: number, emit: EmitGameEvent): void {
124	  const rs = state.redstone;
125	  rs.timer += dt;
126	  if (rs.timer < REDSTONE_TICK_SECONDS) return;
127	  rs.timer = 0;
128	
129	  const { world } = state;
130	  const sizeXZ = world.sizeX * world.sizeZ;
131	  const xOf = (index: number) => index % world.sizeX;
132	  const zOf = (index: number) => Math.floor(index / world.sizeX) % world.sizeZ;
133	  const yOf = (index: number) => Math.floor(index / sizeXZ);
134	  let changed = false;
135	  const write = (x: number, y: number, z: number, block: BlockId) => {
136	    state.blockChanges.set(x, y, z, block);
137	    changed = true;
138	  };
139	
140	  // Phase 1 — inputs & self-heal. Deleting while iterating a Set is safe.
141	  const occupied = collectOccupiedCells(state);
142	  for (const index of rs.cells) {
143	    const block = world.blocks[index];
144	    if (!isRedstoneBlock(block)) {
145	      // Mined, exploded, or overwritten (locally or by a server delta): forget it.
146	      rs.cells.delete(index);
147	      rs.buttonTimers.delete(index);
148	      continue;
149	    }
150	    const x = xOf(index);
151	    const y = yOf(index);
152	    const z = zOf(index);
153	    // An overlay whose support vanished pops off (no drop — whatever removed
154	    // the support, e.g. an explosion, would have vaporized the component too;
155	    // direct mining cascades the drop in mining.ts before this runs).
156	    if (isRedstoneOverlay(block)) {
157	      const support = world.get(x, y - 1, z);
158	      if (!world.isSolid(x, y - 1, z) || isRedstoneOverlay(support) || isDoorBlock(support)) {
159	        write(x, y, z, BlockId.Air);
160	        rs.cells.delete(index);
161	        rs.buttonTimers.delete(index);
162	        continue;
163	      }
164	    }
165	    if (isPressurePlate(block)) {
166	      const pressed = occupied.has(index);
167	      if (pressed !== isRedstoneOn(block)) {
168	        write(x, y, z, pressed ? redstoneOn(block as BlockId) : redstoneOff(block as BlockId));
169	        emit({ type: "plateToggled", on: pressed });
170	      }
171	    }
172	    if (block === BlockId.RedstoneButtonOn) {
173	      // A missing timer entry (a save written mid-press just reloaded) heals
174	      // by popping the button back immediately. The epsilon absorbs float
175	      // drift so the pop lands on the expected pass, not one late.
176	      const left = rs.buttonTimers.get(index);
177	      if (left === undefined || left - REDSTONE_TICK_SECONDS <= 1e-9) {
178	        write(x, y, z, BlockId.RedstoneButton);
179	        rs.buttonTimers.delete(index);
180	      } else {
181	        rs.buttonTimers.set(index, left - REDSTONE_TICK_SECONDS);
182	      }
183	    }
184	  }
185	
186	  // Phase 2 — the power graph, re-derived from the current grid. Sources power
187	  // their six neighbors (a torch skips its own support — the inverter rule);
188	  // wire relaxes outward with a hop budget, powering everything it touches.
189	  const powered = new Set<number>();
190	  const wireBudget = new Map<number, number>();
191	  const queue: number[] = []; // indices with a pending budget in wireBudget
192	  const relax = (x: number, y: number, z: number, budget: number) => {
193	    if (!world.inBounds(x, y, z)) return;
194	    const index = world.index(x, y, z);
195	    if ((wireBudget.get(index) ?? 0) >= budget) return;
196	    wireBudget.set(index, budget);
197	    queue.push(index);
198	  };
199	
200	  for (const index of rs.cells) {
201	    const block = world.blocks[index];
202	    const isSource = block === BlockId.LeverOn || block === BlockId.RedstoneButtonOn || block === BlockId.PressurePlateOn || block === BlockId.RedstoneTorch;
203	    if (!isSource) continue;
204	    const x = xOf(index);
205	    const y = yOf(index);
206	    const z = zOf(index);
207	    const skipSupport = block === BlockId.RedstoneTorch;
208	    for (const [fx, fy, fz] of FACES) {
209	      if (skipSupport && fy === -1) continue;
210	      const nx = x + fx;
211	      const ny = y + fy;
212	      const nz = z + fz;
213	      if (!world.inBounds(nx, ny, nz)) continue;
214	      powered.add(world.index(nx, ny, nz));
215	      if (isRedstoneWire(world.get(nx, ny, nz))) relax(nx, ny, nz, REDSTONE_WIRE_RANGE);
216	    }
217	  }
218	
219	  while (queue.length > 0) {
220	    const index = queue.pop()!;
221	    const budget = wireBudget.get(index)!;
222	    const x = xOf(index);
223	    const y = yOf(index);
224	    const z = zOf(index);
225	    powered.add(index);
226	    for (const [fx, fy, fz] of FACES) {
227	      if (world.inBounds(x + fx, y + fy, z + fz)) powered.add(world.index(x + fx, y + fy, z + fz));
228	    }
229	    if (budget <= 1) continue;
230	    // Wire steps to its four horizontal neighbors at the same level and one
231	    // block up or down (slope climbing).
232	    for (const [hx, hz] of HORIZONTAL) {
233	      for (const dy of [0, 1, -1]) {
234	        const nx = x + hx;
235	        const ny = y + dy;
236	        const nz = z + hz;
237	        if (world.inBounds(nx, ny, nz) && isRedstoneWire(world.get(nx, ny, nz))) relax(nx, ny, nz, budget - 1);
238	      }
239	    }
240	  }
241	
242	  // Phase 3 — outputs, written only on change.
243	  for (const index of rs.cells) {
244	    const block = world.blocks[index];
245	    const x = xOf(index);
246	    const y = yOf(index);
247	    const z = zOf(index);
248	    if (isRedstoneWire(block)) {
249	      const on = wireBudget.has(index);
250	      if (on !== isRedstoneOn(block)) write(x, y, z, on ? redstoneOn(block as BlockId) : redstoneOff(block as BlockId));
251	    } else if (isRedstoneLamp(block)) {
252	      const on = powered.has(index);
253	      if (on !== isRedstoneOn(block)) {
254	        write(x, y, z, on ? redstoneOn(block as BlockId) : redstoneOff(block as BlockId));
255	        emit({ type: "lampToggled", on });
256	      }
257	    } else if (isRedstoneTorch(block)) {
258	      // The inverter: off while the support block is powered. Computed from
259	      // this pass's grid, applied next write — a synchronous clocked update,
260	      // which is what makes a two-torch clock oscillate instead of flicker.
261	      const supportPowered = y > 0 && powered.has(world.index(x, y - 1, z));
262	      const shouldBeOn = !supportPowered;
263	      if (shouldBeOn !== isRedstoneOn(block)) write(x, y, z, shouldBeOn ? redstoneOn(block as BlockId) : redstoneOff(block as BlockId));
264	    }
265	  }
266	
267	  // Consumers outside the tracked set, discovered through the powered cells:
268	  // doors force open/closed on power edges (manual toggling works between
269	  // edges), and powered TNT lights its fuse (primeTnt is idempotent).
270	  const doorPowered = new Set<number>();
271	  for (const index of powered) {
272	    const block = world.blocks[index];
273	    if (block === BlockId.Tnt) {
274	      primeTnt(state, xOf(index), yOf(index), zOf(index), emit);
275	    } else if (isDoorBlock(block)) {
276	      const door = doorState(block)!;
277	      const lowerY = door.upper ? yOf(index) - 1 : yOf(index);
278	      if (lowerY >= 0) doorPowered.add(world.index(xOf(index), lowerY, zOf(index)));
279	    }
280	  }
281	  const forceDoor = (lowerIndex: number, open: boolean) => {
282	    const x = xOf(lowerIndex);
283	    const y = yOf(lowerIndex);
284	    const z = zOf(lowerIndex);
285	    const lower = doorState(world.get(x, y, z));
286	    const upper = doorState(world.get(x, y + 1, z));
287	    if (!lower || lower.upper || !upper?.upper || lower.facing !== upper.facing) return;
288	    if (lower.open === open) return;
289	    write(x, y, z, doorBlock(lower.facing, open, false));
290	    write(x, y + 1, z, doorBlock(lower.facing, open, true));
291	    emit({ type: "doorToggled", open });
292	  };
293	  for (const lowerIndex of doorPowered) {
294	    if (!rs.prevDoorPowered.has(lowerIndex)) forceDoor(lowerIndex, true); // rising edge
295	  }
296	  for (const lowerIndex of rs.prevDoorPowered) {
297	    if (!doorPowered.has(lowerIndex) && isDoorBlock(world.blocks[lowerIndex])) forceDoor(lowerIndex, false); // falling edge
298	  }
299	  rs.prevDoorPowered = doorPowered;
300	
301	  if (changed) state.worldMeshDirty = true;
302	}
303

