25	/**
26	 * Redstone-lite power simulation. Binary signal: on-state sources (lever,
27	 * pressed button/plate, lit redstone torch) power their six face neighbors;
28	 * wire carries the signal up to REDSTONE_WIRE_RANGE wire-to-wire hops (with
29	 * one-block slope climbing) and powers everything it touches. A redstone
30	 * torch is an inverter — it turns off while its support block is powered,
31	 * and never powers its own support, so it cannot feed itself.
32	 *
33	 * The whole pass re-derives power from the block grid at a fixed cadence
34	 * (REDSTONE_TICK_SECONDS) and writes only actual state changes, so a stable
35	 * circuit costs nothing per pass. All effects are block-id swaps through the
36	 * blockChanges.set chokepoint (relight + save diff + net journal for free);
37	 * per-cell bookkeeping self-heals, so mining, explosions, and server-applied
38	 * edits need zero redstone awareness. Runs server-side only in online worlds:
39	 * replicas early-return before world systems and receive the resulting block
40	 * deltas through the tick journal like any other edit.
41	 */
42	
43	export function createRedstoneState(): RedstoneState {
44	  return { cells: new Set(), buttonTimers: new Map(), prevDoorPowered: new Set(), timer: 0 };
45	}
46	
47	/**
48	 * Boot-time seeding: every redstone block is craft-only, hence player-placed,
49	 * hence present in the save's block diff — scanning it recovers the full
50	 * component set with no persistence of our own. Rails (plain included) are
51	 * tracked too: the pass owns their support-pop, detector toggling, and
52	 * powered-rail output.
53	 */
54	export function seedRedstoneCells(state: GameState): void {
55	  for (const [index, block] of state.blockChanges.changes()) {
56	    if (isRedstoneBlock(block) || isRailBlock(block)) state.redstone.cells.add(index);
57	  }
58	}
59	
60	/** The placement seam: track a freshly placed component (any redstone id). */
61	export function trackRedstoneCell(state: GameState, x: number, y: number, z: number): void {
62	  state.redstone.cells.add(state.world.index(x, y, z));
63	}
64	
65	/** Right-click on a lever: flip it and let the next pass propagate. */
66	export function toggleLever(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
67	  const block = state.world.get(x, y, z);
68	  if (!isLever(block)) return false;
69	  const next = isRedstoneOn(block) ? redstoneOff(block as BlockId) : redstoneOn(block as BlockId);
70	  state.blockChanges.set(x, y, z, next);
71	  state.redstone.cells.add(state.world.index(x, y, z));
72	  state.worldMeshDirty = true;
73	  emit({ type: "leverToggled", on: isRedstoneOn(next) });
74	  return true;
75	}
76	
77	/** Right-click on a button: press it and arm the pop-back timer. */
78	export function pressButton(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
79	  const block = state.world.get(x, y, z);
80	  if (!isRedstoneButton(block)) return false;
81	  // Already pressed: consume the click (re-pressing does not extend the timer).
82	  if (isRedstoneOn(block)) return true;
83	  state.blockChanges.set(x, y, z, redstoneOn(block as BlockId));
