21	function mulberry32(seed: number): () => number {
22	  let t = seed >>> 0;
23	  return () => {
24	    t += 0x6d2b79f5;
25	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
26	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
27	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
28	  };
29	}
