    for (let i = 0; i < 32; i += 1) {
      const angle = (Math.PI * 2 * i) / 32;
      const x = Math.max(5, Math.min(world.sizeX - 6, Math.floor(centerX + Math.cos(angle) * radius)));
      const z = Math.max(5, Math.min(world.sizeZ - 6, Math.floor(centerZ + Math.sin(angle) * radius)));
      const topY = world.highestSolidY(x, z);
      const y = topY + 1;
      if (isGoodSpawn(x, y, z)) return { x, y, z };
    }
  }

  if (seekPlains) return findSpawnOnLand(world, centerX, centerZ, false);

  const topY = world.highestSolidY(centerX, centerZ);
  return { x: centerX, y: topY + 1, z: centerZ };
}

/** True when the surface position is dry: not a flooded column (seabed/lake floor). */
function isDrySurface(world: VoxelWorld, x: number, y: number, z: number): boolean {
  return world.get(Math.floor(x), y, Math.floor(z)) !== BlockId.Water;
}

export function randomLandPoint(world: VoxelWorld, surfaceYAt: SurfaceYAtFn, rng: () => number = Math.random): THREE.Vector3 {
  for (let i = 0; i < 40; i += 1) {
    const x = 10 + rng() * (world.sizeX - 20);
    const z = 10 + rng() * (world.sizeZ - 20);
    const y = surfaceYAt(x, z);
    if (y > 2 && isDrySurface(world, x, y, z)) return new THREE.Vector3(x, y, z);
  }
  return new THREE.Vector3(world.sizeX / 2, 12, world.sizeZ / 2);
}

/**
 * A random swim point in open water near (centerX, centerZ): a column whose
 * floor holds at least `minDepth` water above it, at mid-depth so the fish
 * starts fully submerged. Returns null when no water is found (a dry world or
 * an inland center) — callers must fail closed rather than spawn on land.
 */
export function randomWaterPointNear(
  world: VoxelWorld,
  centerX: number,
  centerZ: number,
  radius: number,
  rng: () => number = Math.random,
  minDepth = 2,
  minRadius = 0
): THREE.Vector3 | null {
  for (let i = 0; i < 50; i += 1) {
    const x = Math.max(10, Math.min(world.sizeX - 10, centerX + (rng() * 2 - 1) * radius));
    const z = Math.max(10, Math.min(world.sizeZ - 10, centerZ + (rng() * 2 - 1) * radius));
    // A standoff for hostile spawns (mirrors randomLandPointNear's minRadius):
    // nothing should materialize point-blank under a swimming player.
    if (minRadius > 0 && Math.hypot(x - centerX, z - centerZ) < minRadius) continue;
    const ix = Math.floor(x);
    const iz = Math.floor(z);
    const floor = world.highestSolidY(ix, iz);
    let depth = 0;
    while (world.get(ix, floor + 1 + depth, iz) === BlockId.Water) depth += 1;
    if (depth < minDepth) continue;
    const y = floor + 1 + Math.floor(depth / 2) + 0.5;
    return new THREE.Vector3(x, y, z);
  }
  return null;
}

export function randomLandPointNear(
  world: VoxelWorld,
  surfaceYAt: SurfaceYAtFn,
  centerX: number,
  centerZ: number,
  radius: number,
  rng: () => number = Math.random,
  minRadius = 0
): THREE.Vector3 {
  for (let i = 0; i < 50; i += 1) {
    const x = centerX + (rng() * 2 - 1) * radius;
    const z = centerZ + (rng() * 2 - 1) * radius;
    const clampedX = Math.max(10, Math.min(world.sizeX - 10, x));
    const clampedZ = Math.max(10, Math.min(world.sizeZ - 10, z));
    // Keep a minimum standoff so a mob can't spawn on top of the player.
    if (minRadius > 0 && Math.hypot(clampedX - centerX, clampedZ - centerZ) < minRadius) continue;
    const y = surfaceYAt(clampedX, clampedZ);
    if (y > 2 && isDrySurface(world, clampedX, y, clampedZ)) return new THREE.Vector3(clampedX, y, clampedZ);
  }
  return randomLandPoint(world, surfaceYAt, rng);
}

